def peopleAwareOfSecret(n, delay, forget):
    MOD = 10 ** 9 + 7
    know = [0] * (n + 1)
    know[1] = 1
    for i in range(1, n + 1):
        if know[i]:
            for d in range(i + delay, min(n, i + forget - 1) + 1):
                know[d] = (know[d] + know[i]) % MOD
    ans = 0
    for i in range(max(1, n - forget + 1), n + 1):
        ans = (ans + know[i]) % MOD
    return ans
